def is_nested(string):
    if not all(char in '[]' for char in string):
        return False

    def is_balanced(s):
        stack = []
        for char in s:
            if char == '[':
                stack.append(char)
            elif char == ']':
                if not stack or stack[-1] != '[':
                    return False
                stack.pop()
        return not stack

    for i in range(len(string)):
        for j in range(i+1, len(string)+1):
            if is_balanced(string[i:j]):
                return True
    return False

